package httpapi
import ("io"; "net/http"; "os"; "pollen-push-gateway/internal/auth")
func Accept(w http.ResponseWriter, r *http.Request) {
    body, err := io.ReadAll(r.Body)
    if err != nil { http.Error(w, "BODY_READ", 400); return }
    if !auth.AllowPush(body, r.Header.Get("X-Pollen-Signature"), []byte(os.Getenv("PUSH_KEY"))) {
        http.Error(w, "PUSH_AUTH", 401); return
    }
    w.WriteHeader(202)
}

