package auth
import ("crypto/hmac"; "crypto/sha256"; "encoding/hex")
func SignBody(body, key []byte) []byte {
    mac := hmac.New(sha256.New, key)
    mac.Write(body)
    return mac.Sum(nil)
}
func EqualSignedBody(body []byte, signature string, key []byte) bool {
    supplied, err := hex.DecodeString(signature)
    if err != nil { return false }
    return hmac.Equal(supplied, SignBody(body, key))
}
